<?php require __DIR__.'/bootstrap.php'; $db=ledger_db(); $plan=in_array('--plan',$argv,true); $db->exec('CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(64) NOT NULL PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci'); foreach(glob(dirname(__DIR__).'/migrations/*.sql') as $file){$version=basename($file,'.sql');$s=$db->prepare('SELECT 1 FROM schema_migrations WHERE version=?');$s->execute([$version]);if($s->fetchColumn())continue;echo ($plan?'PLAN ':'APPLY ').$version.PHP_EOL;if($plan)continue;$db->exec(file_get_contents($file));$db->prepare('INSERT INTO schema_migrations(version) VALUES(?)')->execute([$version]);}
